import {useState,useEffect,useCallback,useMemo,type ReactNode} from 'react';
import {Home,Layers,Compass,Boxes,Image as ImageIcon,Server as ServerIcon,Shirt,Users,Download,Settings,Search,Bell,Minus,Square,X,ChevronDown,ChevronRight,ChevronLeft,Plus,Play,ArrowUpRight,SlidersHorizontal,MoreHorizontal,Check,CheckCircle2,AlertCircle,RefreshCw,FolderOpen,Copy,Trash2,ExternalLink,LogIn,LogOut,Shield,Monitor,Zap,Leaf,Swords,HardDrive,Activity,Clock,Globe,Wifi,Eye,EyeOff,ArrowDownToLine,Upload,Palette,Gamepad2,Lock,Info,MessageCircle,Volume2,Star,ChevronUp,LoaderCircle,Terminal,Package,Code,Keyboard,Mail,ArrowLeft,CheckCheck,ArrowRight} from 'lucide-react';
import type {LucideIcon} from 'lucide-react';
import {type Snapshot,type Page,type Profile,type Project,type ProjectDetail,type SearchQuery,type Settings as SettingsType,PRESETS} from './shared';
import {previewBridge} from './preview';
import {DiscordIntegration} from './DiscordIntegration';
import {PerformancePage} from './PerformancePage';
import {ModCollection} from './ModCollection';
import {OfficialConnection,LaunchModeField} from './OfficialConnection';
import {UpdatePanel,AccountValidation,ProfileValidation} from './ReleasePanels';
import {Button,IconButton,Brand,Badge,PageHead,Empty,Loading,Modal,SectionHead,ProfileCard,ProjectCard,ProjectArt,ProfileArt,Field,Toggle} from './components';
const bridge=window.vsync??previewBridge;
const nav:{id:Page;name:string;icon:LucideIcon;group?:string}[]=[
 {id:'home',name:'Início',icon:Home,group:'JOGAR'},{id:'profiles',name:'Meus perfis',icon:Layers},{id:'fps',name:'FPS',icon:Zap},
 {id:'modpacks',name:'Explorar modpacks',icon:Compass,group:'DESCOBRIR'},{id:'mods',name:'Mods',icon:Boxes},{id:'textures',name:'Texturas e shaders',icon:ImageIcon},{id:'servers',name:'Servidores',icon:ServerIcon},
 {id:'cosmetics',name:'Cosméticos',icon:Shirt,group:'VSYNC'},{id:'friends',name:'Amigos',icon:Users},{id:'downloads',name:'Downloads',icon:Download},{id:'settings',name:'Configurações',icon:Settings}
];
const settingsTabs=[['Geral',SlidersHorizontal],['Aparência',Palette],['Minecraft e Java',Gamepad2],['Contas',Shield],['Downloads',Download],['Privacidade',Eye],['Integrações',Globe],['Avançado',Terminal]] as const;
type ModalState={type:'profile';profile?:Profile;preset?:number}|{type:'project';project:Project}|{type:'server'}|{type:'export';profile:Profile}|{type:'news';index:number}|{type:'info';title:string;text:string}|null;
const news=[{tag:'LANÇAMENTO',date:'VERSÃO 0.1.2',title:'Um novo jeito de jogar.',description:'Conheça a primeira versão do Vsync: seus perfis, seus mods, sua identidade.',body:'Esta é a versão inicial do Vsync Client. O launcher instala versões oficiais do Minecraft, mantém pastas isoladas e conecta o catálogo Modrinth. No modo oficial, entre com a Microsoft no Minecraft Launcher original. A nova aba FPS ajusta opções por perfil. O HUD Vsync é um módulo Fabric separado.'},{tag:'DENTRO DO JOGO',date:'FABRIC 1.21.1',title:'O essencial, na sua tela.',description:'FPS, keystrokes e um HUD que combina com você.',body:'O módulo Vsync HUD é instalado separadamente no perfil Fabric 1.21.1 e exige Fabric API. Right Shift abre seu menu. Arraste os elementos no editor e escolha um preset. A compilação e a validação estão descritas no projeto.'}];
const bytes=(v:number)=>v>=1e9?(v/1e9).toFixed(1)+' GB':v>=1e6?(v/1e6).toFixed(1)+' MB':v>=1e3?(v/1e3).toFixed(0)+' KB':Math.round(v)+' B';
export default function App(){
 const [state,setState]=useState<Snapshot|null>(null),[page,setPage]=useState<Page>('home'),[friendsOpen,setFriendsOpen]=useState(true),[modal,setModal]=useState<ModalState>(null),[toast,setToast]=useState<{message:string;error:boolean}|null>(null),[busy,setBusy]=useState(0),[notifications,setNotifications]=useState(false),[settingsTab,setSettingsTab]=useState('Geral');
 const [catalogQuery,setCatalogQuery]=useState(''),[category,setCategory]=useState(''),[sort,setSort]=useState('downloads'),[textureType,setTextureType]=useState<'resourcepack'|'shader'>('resourcepack'),[library,setLibrary]=useState(false),[profileSearch,setProfileSearch]=useState('');
 const [projects,setProjects]=useState<Project[]>([]),[catalogLoading,setCatalogLoading]=useState(false),[catalogError,setCatalogError]=useState(''),[reload,setReload]=useState(0),[totalProjects,setTotalProjects]=useState(0),[catalogOffset,setCatalogOffset]=useState(0),[recommended,setRecommended]=useState(false);
 const [featured,setFeatured]=useState<Project[]>([]),[featuredError,setFeaturedError]=useState(''),[featuredLoading,setFeaturedLoading]=useState(true);
 const [cosmetic,setCosmetic]=useState('Capa Eclipse'),[serverStatus,setServerStatus]=useState<Record<string,any>>({});
 const notify=useCallback((message:string,error=false)=>setToast({message,error}),[]);
 const run=useCallback(async<T,>(method:string,args?:unknown,success?:string):Promise<T|undefined>=>{setBusy(b=>b+1);try{const result=await bridge.call<T>(method,args);if(success)notify(success);return result;}catch(e){notify((e as Error).message,true);return undefined;}finally{setBusy(b=>b-1);}},[notify]);
 useEffect(()=>{void bridge.call<Snapshot>('snapshot').then(setState).catch(e=>notify(e.message,true));return bridge.subscribe(setState);},[notify]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(null),6500);return()=>clearTimeout(timer);},[toast]);
 const profile=state?.profiles.find(p=>p.id===state.selectedProfileId);
 const account=state?.settings.launchMode==='official'?undefined:state?.accounts.find(a=>a.id===state.activeAccountId);
 const catalogType=page==='modpacks'?'modpack':page==='textures'?textureType:'mod';
 const go=(p:Page)=>{setPage(p);setNotifications(false);setLibrary(false);setRecommended(false);setCatalogOffset(0);setCatalogQuery('');};
 const settings=(tab:string)=>{go('settings');setSettingsTab(tab);};
 const selectedProfileId=profile?.id;
 useEffect(()=>{if(!profile)return;let live=true;setFeaturedLoading(true);setFeaturedError('');bridge.call<any>('catalog.search',{query:'',type:'modpack',version:profile.gameVersion,loader:'',sort:'downloads',category:''}).then(r=>{if(live)setFeatured(r.hits.slice(0,3));}).catch(e=>{if(live)setFeaturedError(e.message);}).finally(()=>{if(live)setFeaturedLoading(false);});return()=>{live=false;};},[profile?.gameVersion]);
 useEffect(()=>setCatalogOffset(0),[page,catalogQuery,catalogType,profile?.id,profile?.gameVersion,profile?.loader,category,sort]);
 useEffect(()=>{
  if(!['modpacks','mods','textures'].includes(page)||!profile||library||recommended)return;let live=true;setCatalogLoading(true);setCatalogError('');const timer=setTimeout(()=>{const query:SearchQuery={query:catalogQuery,type:catalogType,version:profile.gameVersion,loader:profile.loader==='vanilla'?'':profile.loader,sort,category,offset:catalogOffset};bridge.call<any>('catalog.search',query).then(result=>{if(live){setProjects(result.hits);setTotalProjects(result.total_hits);}}).catch(e=>{if(live)setCatalogError(e.message);}).finally(()=>{if(live)setCatalogLoading(false);});},250);return()=>{live=false;clearTimeout(timer);};
 },[page,catalogQuery,catalogType,profile?.gameVersion,profile?.loader,category,sort,library,recommended,catalogOffset,reload]);
 useEffect(()=>{document.documentElement.style.setProperty('--accent',state?.settings.accent??'#8B5CF6');document.documentElement.style.setProperty('--ui-scale',String(state?.settings.scale??1));document.body.classList.toggle('reduce-motion',state?.settings.animations===false||state?.game.state==='running'&&state.settings.reduceInGame===true);},[state?.settings,state?.game.state]);
 const saveSettings=(changes:Partial<SettingsType>)=>void run('settings.save',changes);
 if(!state)return <div className="boot"><Brand large/><Loading label="Preparando seu espaço…"/></div>;
 const activeTasks=state.tasks.filter(t=>['queued','running'].includes(t.status));
 const officialMode=state.settings.launchMode==='official';
 const launchLabel=state.game.state==='running'?'EM EXECUÇÃO':state.game.state==='preparing'||officialMode&&state.official.status==='preparing'?'PREPARANDO':activeTasks.length?'BAIXANDO':officialMode?'ABRIR LAUNCHER':profile?.installed?'JOGAR':'INSTALAR';
 const launch=()=>{if(!profile){setModal({type:'profile'});return;}if(officialMode){if(['missing','unsupported','error'].includes(state.official.status)){settings('Contas');notify(state.official.message,true);return;}void run('profile.launch',{id:profile.id},'Preparando o perfil. Continue no Minecraft Launcher quando ele abrir.');return;}if(profile.installed&&!account){settings('Contas');notify('Entre com sua conta Microsoft para jogar.');return;}void run(profile.installed?'profile.launch':'profile.install',{id:profile.id},profile.installed?undefined:'Instalação adicionada à fila.');};
 const modalClose=()=>setModal(null);
 const info=(title:string,text:string)=>setModal({type:'info',title,text});
 const installProject=(project:Project,versionId?:string)=>{if(!profile)return;void run('catalog.install',{profileId:profile.id,project:project.id,versionId},'Instalação adicionada à fila de downloads.').then(r=>{if(r)setModal(null);});};
 const renderCatalog=()=>{
  const titles=page==='modpacks'?['Explore novas possibilidades.','Encontre o próximo modpack para chamar de seu.']:page==='textures'?['Um novo olhar para o seu mundo.','Texturas e shaders para deixar tudo com a sua cara.']:['Pequenos mods. Grandes possibilidades.','Descubra novas formas de jogar, construir e explorar.'];
  return <><PageHead eyebrow="DESCUBRA SEU PRÓXIMO MUNDO" title={titles[0]} subtitle={titles[1]}><Badge tone="muted"><Globe size={12}/> Modrinth</Badge></PageHead>
   <div className="tabs-row"><div className="tabs"><button className={!library&&!recommended?'active':''} onClick={()=>{setLibrary(false);setRecommended(false);}}>Explorar</button>{page==='mods'&&<button className={recommended?'active':''} onClick={()=>{setLibrary(false);setRecommended(true);}}>Recomendados</button>}<button className={library?'active':''} onClick={()=>{setLibrary(true);setRecommended(false);}}>Instalados <span>{profile?.components.filter(c=>page==='mods'?c.type==='mod':c.type!=='mod').length??0}</span></button></div><span className="linked-profile"><Layers size={13}/>{profile?.name??'Selecione um perfil'}</span></div>
   {library?renderLibrary():!profile?<Empty icon={<Layers/>} title="Crie seu primeiro perfil" description="O catálogo usa a versão e o loader do perfil selecionado para encontrar os arquivos certos."><Button variant="primary" onClick={()=>setModal({type:'profile'})}><Plus size={16}/>Criar perfil</Button></Empty>:recommended&&page==='mods'?<ModCollection key={profile.id} state={state} profile={profile} bridge={bridge} run={run} busy={busy>0} onOpen={project=>setModal({type:'project',project})}/>:<>
    <div className="catalog-tools"><div className="search-input"><Search size={18}/><input placeholder="Busque sua próxima descoberta…" value={catalogQuery} onChange={e=>setCatalogQuery(e.target.value)}/>{catalogQuery&&<IconButton label="Limpar busca" onClick={()=>setCatalogQuery('')}><X size={14}/></IconButton>}</div><select aria-label="Ordenar catálogo" value={sort} onChange={e=>setSort(e.target.value)}><option value="downloads">Mais populares</option><option value="relevance">Relevância</option><option value="updated">Atualizados recentemente</option><option value="newest">Mais recentes</option></select></div>
    <div className="filter-row"><span className="filter-label"><SlidersHorizontal size={14}/>Filtros</span><Badge tone="muted">{profile.gameVersion}</Badge>{page!=='textures'&&<Badge tone="muted"><span className="capitalize">{profile.loader}</span></Badge>}{page==='textures'?<><button className={'filter-chip '+(textureType==='resourcepack'?'active':'')} onClick={()=>setTextureType('resourcepack')}>Resource packs</button><button className={'filter-chip '+(textureType==='shader'?'active':'')} onClick={()=>setTextureType('shader')}>Shaders</button></>:<><button className={'filter-chip '+(category===''?'active':'')} onClick={()=>setCategory('')}>Todos</button><button className={'filter-chip '+(category==='optimization'?'active':'')} onClick={()=>setCategory('optimization')}>Desempenho</button><button className={'filter-chip '+(category==='adventure'?'active':'')} onClick={()=>setCategory('adventure')}>Aventura</button><button className={'filter-chip '+(category==='technology'?'active':'')} onClick={()=>setCategory('technology')}>Tecnologia</button></>}</div>
    {catalogLoading?<div className="skeleton-grid">{[0,1,2,3,4,5].map(x=><div className="skeleton" key={x}/>)}</div>:catalogError?<Empty icon={<AlertCircle/>} title="Não foi possível carregar o catálogo" description={catalogError}><Button onClick={()=>setReload(x=>x+1)}><RefreshCw size={16}/>Tentar novamente</Button></Empty>:projects.length?<><div className="results-count">{totalProjects.toLocaleString('pt-BR')} projetos encontrados <span>Exibindo {catalogOffset+1}–{catalogOffset+projects.length}</span></div><div className="project-grid">{projects.map((p,i)=><ProjectCard key={p.id} project={p} index={i} onOpen={()=>setModal({type:'project',project:p})}/>)}</div><div className="fps-control-footer" aria-label="Paginação do catálogo"><span>Página {Math.floor(catalogOffset/24)+1} de {Math.max(1,Math.ceil(totalProjects/24))}</span><div><Button disabled={catalogOffset===0} onClick={()=>setCatalogOffset(value=>Math.max(0,value-24))}><ChevronLeft size={15}/>Página anterior</Button><Button disabled={catalogOffset+projects.length>=totalProjects} onClick={()=>setCatalogOffset(value=>value+24)}>Próxima página<ChevronRight size={15}/></Button></div></div></>:<Empty icon={<Search/>} title="Nenhum projeto por aqui" description="Tente outra busca ou ajuste a categoria. O catálogo considera a compatibilidade com seu perfil."><Button onClick={()=>{setCatalogQuery('');setCategory('');setCatalogOffset(0);}}>Limpar filtros</Button></Empty>}
    <p className="footnote"><Shield size={13}/> Arquivos verificados por hash. Dependências declaradas são resolvidas antes da instalação.</p>
   </>}
  </>;
 };
 const renderLibrary=()=>{
  const components=profile?.components.filter(c=>page==='mods'?c.type==='mod':page==='textures'?c.type!=='mod':true)??[];
  return components.length?<div className="installed-list">{components.map(c=><div className="installed-row" key={c.id}><div className="component-icon"><Package size={22}/></div><div className="grow"><h3>{c.name}</h3><p>{c.version} • {c.type}</p></div><Badge tone={c.enabled?'green':'muted'}>{c.enabled?'Ativo':'Desativado'}</Badge><Toggle checked={c.enabled} onChange={()=>void run('component.toggle',{profileId:profile?.id,id:c.id})} label={'Ativar '+c.name}/><IconButton label={'Atualizar '+c.name} onClick={()=>void run('component.update',{profileId:profile?.id,id:c.id})}><RefreshCw size={16}/></IconButton><IconButton label={'Remover '+c.name} onClick={()=>void run('component.remove',{profileId:profile?.id,id:c.id},'Componente removido. Um backup foi preservado.')}><Trash2 size={16}/></IconButton></div>)}</div>:<Empty icon={<Boxes size={34}/>} title="Sua coleção começa aqui" description="Instale componentes pelo catálogo. Eles ficam separados em cada perfil. Arquivos de modpacks importados também ficam na pasta do perfil."><Button variant="primary" onClick={()=>setLibrary(false)}><Compass size={17}/>Explorar catálogo</Button><Button onClick={()=>profile&&void run('profile.folder',{id:profile.id})}><FolderOpen size={16}/>Abrir pasta</Button></Empty>;
 };
 const renderHome=()=> <>
  <PageHead title="Início" subtitle="Tudo pronto para a sua próxima aventura."><span className="edition"><span/>Minecraft Java Edition</span></PageHead>
  <section className="hero"><div className="hero-art"/><div className="hero-shade"/><div className="hero-content"><div className="hero-tag"><span/> O SEU PRÓXIMO CAPÍTULO</div><p className="hero-welcome">{account?'Bem-vindo de volta, '+account.name+'.':'Sua próxima aventura começa aqui.'}</p><h2>Seu mundo.<br/><span>Seu ritmo.</span></h2><p className="hero-description">Uma experiência feita para ir além.<br/>Entre, explore e faça do seu jeito.</p><div className="hero-actions"><Button variant="primary" className="hero-play" onClick={launch} disabled={activeTasks.length>0||['running','preparing'].includes(state.game.state)}>{activeTasks.length?<LoaderCircle className="spin" size={19}/>:<Play fill="currentColor" size={18}/>} {launchLabel}<ArrowUpRight size={19}/></Button><IconButton label="Configurar perfil selecionado" onClick={()=>profile&&setModal({type:'profile',profile})}><SlidersHorizontal size={19}/></IconButton></div><div className="hero-version"><span className="tiny-dot"/>{profile?.name??'Crie seu perfil'}<span>•</span>{profile?.gameVersion??'Minecraft'}<span className="capitalize">{profile?.loader}</span></div></div><div className="hero-brand"><Brand large/><div className="hero-brand-note"><span/> BUILT FOR YOUR NEXT ADVENTURE</div></div><div className="hero-corner">VSYNC / 01</div></section>
  <div className="quick-strip"><button onClick={()=>setModal({type:'profile'})}><Layers size={18}/><span>Um perfil para cada mundo<small>Instalações organizadas e independentes</small></span><Plus size={17}/></button><span className="quick-divider"/><button onClick={()=>go('mods')}><Zap size={18}/><span>Mais possibilidades, menos limites<small>Descubra mods para a sua versão</small></span><ArrowUpRight size={17}/></button></div>
  <SectionHead title="Seus perfis" subtitle="Do último mundo para a próxima aventura." onClick={()=>go('profiles')}/><div className="home-profiles">{state.profiles.slice(0,2).map(p=><ProfileCard key={p.id} profile={p} modeLabel={officialMode?'Via Minecraft Launcher':undefined} selected={p.id===state.selectedProfileId} onSelect={()=>void run('profile.select',{id:p.id})} onEdit={()=>setModal({type:'profile',profile:p})}/>)}<button className="new-profile-mini" onClick={()=>setModal({type:'profile'})}><span><Plus size={20}/></span><div>Criar perfil<small>Seu próximo começo</small></div></button></div>
  <SectionHead title="Uma nova aventura espera por você" subtitle="Modpacks para dar outro sentido ao seu Minecraft." onClick={()=>go('modpacks')} action="Explorar modpacks"/>
  {featuredLoading?<div className="skeleton-grid small">{[0,1,2].map(x=><div className="skeleton" key={x}/>)}</div>:featuredError?<div className="inline-message"><AlertCircle size={17}/><span>O catálogo está indisponível no momento.</span><button onClick={()=>go('modpacks')}>Tentar novamente<ArrowRight size={14}/></button></div>:featured.length?<div className="project-grid featured">{featured.map((p,i)=><ProjectCard key={p.id} project={p} index={i} onOpen={()=>setModal({type:'project',project:p})}/>)}</div>:<div className="inline-message"><Compass size={17}/>Nenhum modpack encontrado para esta versão.<button onClick={()=>go('profiles')}>Trocar perfil</button></div>}
  <SectionHead title="Dentro do Vsync" onClick={()=>setModal({type:'news',index:0})} action="Saiba mais"/><div className="news-grid">{news.map((n,i)=><button className="news-card" key={n.title} onClick={()=>setModal({type:'news',index:i})}><div className={'news-icon ni-'+i}>{i?<Keyboard size={32}/>:<img src="./assets/mark-mono.svg" alt=""/>}</div><div><div className="news-meta"><span>{n.tag}</span>{n.date}</div><h3>{n.title}</h3><p>{n.description}</p></div><ArrowUpRight size={17}/></button>)}</div>
 </>;
 const renderProfiles=()=> <><PageHead title="Meus perfis" subtitle="Cada aventura merece o seu próprio espaço."><Button onClick={()=>void run('profile.import')}><Upload size={16}/>Importar</Button><Button variant="primary" onClick={()=>setModal({type:'profile'})}><Plus size={17}/>Criar perfil</Button></PageHead><div className="catalog-tools"><div className="search-input"><Search size={18}/><input value={profileSearch} onChange={e=>setProfileSearch(e.target.value)} placeholder="Encontrar um perfil…"/></div><Badge tone="muted">{state.profiles.length} perfis</Badge></div>
 {state.profiles.length?<div className="profiles-grid">{state.profiles.filter(p=>p.name.toLowerCase().includes(profileSearch.toLowerCase())).map(p=><div className={'full-profile '+(p.id===state.selectedProfileId?'active':'')} key={p.id}><div className="full-profile-art"><ProfileArt preset={p.preset} image={p.image}/><Badge tone={officialMode?'purple':p.installed?'green':'muted'}>{officialMode?'Launcher oficial':p.installed?'Instalado':'Não instalado'}</Badge>{p.id===state.selectedProfileId&&<span className="full-profile-selected"><CheckCircle2 size={16}/>Selecionado</span>}</div><div className="full-profile-copy"><h2>{p.name}</h2><p>{p.description}</p><div className="profile-specs"><span><Gamepad2 size={13}/>{p.gameVersion}</span><span className="capitalize">{p.loader}</span><span><HardDrive size={13}/>{(p.ram/1024).toFixed(0)} GB</span></div><div className="full-profile-actions"><Button variant={p.id===state.selectedProfileId?'primary':'secondary'} onClick={()=>void run('profile.select',{id:p.id})}>{p.id===state.selectedProfileId?<Check size={15}/>:<Play size={15}/>} {p.id===state.selectedProfileId?'Selecionado':'Selecionar'}</Button><IconButton label={'Editar '+p.name} onClick={()=>setModal({type:'profile',profile:p})}><Settings size={16}/></IconButton><IconButton label={'Abrir pasta '+p.name} onClick={()=>void run('profile.folder',{id:p.id})}><FolderOpen size={16}/></IconButton></div></div></div>)}</div>:<Empty icon={<Layers/>} title="Seu primeiro mundo está por vir" description="Crie um perfil para escolher sua versão, seu loader e seus mods."><Button variant="primary" onClick={()=>setModal({type:'profile'})}><Plus size={16}/>Criar perfil</Button></Empty>}
 <SectionHead title="Encontre seu jeito de jogar" subtitle="Bases Vsync para começar. Você escolhe os componentes."/><div className="preset-grid">{PRESETS.map((p,i)=><button key={p.name} className="preset-card" onClick={()=>setModal({type:'profile',preset:i})}><div className={'preset-icon pi-'+i}>{i===0?<Zap/>:i===1?<Leaf/>:i===2?<Swords/>:<Boxes/>}</div><h3>{p.name.replace('Vsync ','')}</h3><p>{p.description}</p><small>1.21.1 • Fabric • {p.ram/1024} GB</small><span>Criar perfil<Plus size={14}/></span></button>)}</div><div className="info-panel"><Shield size={20}/><p>Cada perfil mantém seus próprios mods, configurações e mundos. O cache oficial do jogo é compartilhado para economizar espaço.</p></div></>;
 const renderServers=()=> <><PageHead title="O próximo encontro é aqui." subtitle="Seus servidores favoritos, a um clique de distância."><Button variant="primary" onClick={()=>setModal({type:'server'})}><Plus size={16}/>Adicionar servidor</Button></PageHead>{state.servers.length?<div className="server-list">{[...state.servers].sort((a,b)=>Number(b.favorite)-Number(a.favorite)).map(s=><div className="server-card" key={s.id}><div className="server-icon"><ServerIcon size={30}/></div><div className="grow"><h3>{s.name}{s.favorite&&<Star size={14} fill="currentColor"/>}</h3><p>{s.address}</p><small>Perfil: {state.profiles.find(p=>p.id===s.profileId)?.name??'Perfil removido'}</small></div>{serverStatus[s.id]?<div className="server-status"><Badge tone={serverStatus[s.id].online?'green':'muted'}>{serverStatus[s.id].online?'Online':'Indisponível'}</Badge><small>{serverStatus[s.id].online?serverStatus[s.id].latency+' ms • '+serverStatus[s.id].players+'/'+serverStatus[s.id].max:serverStatus[s.id].message}</small><small>{serverStatus[s.id].version}</small></div>:<Button variant="ghost" onClick={()=>void run('server.ping',{id:s.id}).then(r=>r&&setServerStatus(v=>({...v,[s.id]:r})))}><Wifi size={15}/>Verificar status</Button>}<Button variant="primary" onClick={()=>void run('server.connect',{id:s.id},officialMode?'Abra o perfil no launcher oficial e use este endereço em Multiplayer.':undefined)}><Play size={15}/>{officialMode?'Abrir perfil':'Conectar'}</Button><IconButton label="Alternar favorito" onClick={()=>void run('server.save',{...s,favorite:!s.favorite})}><Star fill={s.favorite?'currentColor':'none'} size={17}/></IconButton><IconButton label={'Remover servidor '+s.name} onClick={()=>void run('server.delete',{id:s.id})}><Trash2 size={16}/></IconButton></div>)}</div>:<Empty icon={<ServerIcon size={36}/>} title="Um lugar para jogar junto" description="Adicione um servidor, associe um perfil e volte para ele sempre que quiser."><Button variant="primary" onClick={()=>setModal({type:'server'})}><Plus size={16}/>Adicionar seu primeiro servidor</Button></Empty>}<div className="info-panel"><Info size={19}/><p>O status usa o protocolo de consulta Java. Alguns servidores ocultam a versão ou bloqueiam consultas; a ausência de resposta não confirma que estejam offline.</p></div></>;
 const renderFriends=()=> <><PageHead title="As melhores aventuras são compartilhadas." subtitle="Um espaço para a sua próxima comunidade."><Badge tone="yellow">Em desenvolvimento</Badge></PageHead><div className="social-hero"><div className="social-orbits"><div/><div/><div/><span><Users size={48}/></span></div><h2>Seu grupo. Seu próximo mundo.</h2><p>Amigos, presença e convites de servidor farão parte do serviço social Vsync.</p><Badge tone="muted"><Lock size={12}/>Serviço ainda não conectado</Badge></div><div className="social-feature-grid">{[[Users,'Amigos e solicitações','Encontre seu grupo e gerencie quem pode entrar em contato.'],[MessageCircle,'Conversas e convites','Combine a próxima partida sem sair do seu launcher.'],[EyeOff,'Privacidade por escolha','Oculte sua presença e o servidor em que está jogando.'],[Shield,'Você no controle','Bloqueio e denúncia previstos no serviço social.']].map(([Icon,title,text])=>{const I=Icon as LucideIcon;return <div className="feature-tile" key={String(title)}><I size={22}/><h3>{String(title)}</h3><p>{String(text)}</p><Badge tone="muted">Planejado</Badge></div>})}</div><Button onClick={()=>settings('Privacidade')}><Shield size={16}/>Preferências de privacidade</Button></>;
 const renderCosmetics=()=> <><PageHead title="Seu estilo também joga." subtitle="Uma identidade que acompanha as suas aventuras."><Badge tone="yellow">Prévia visual</Badge></PageHead><div className="cosmetic-layout"><div className="character-preview"><div className="character-glow"/><div className="minecraft-character"><div className="character-head"><img src="./assets/panda.png" alt="Cabeça do personagem panda"/></div><div className="character-body" style={{background:cosmetic==='Capa Bambu'?'#4c7860':cosmetic==='Badge Vsync'?'#c4b5fd':'#7c3aed'}}><img src="./assets/mark-mono.svg" alt=""/></div><div className="character-arm left"/><div className="character-arm right"/><div className="character-leg left"/><div className="character-leg right"/><div className="character-cape"/></div><div className="character-floor"/><span className="character-caption">PERSONAGEM CONCEITUAL • PRÉVIA LOCAL</span></div><div className="cosmetics-panel"><h2>Coleção Vsync Originals</h2><p>Inspirada no panda. Feita para o seu mundo.</p>{['Capa Eclipse','Capa Bambu','Badge Vsync'].map((c,i)=><button key={c} className={'cosmetic-item '+(cosmetic===c?'active':'')} onClick={()=>setCosmetic(c)}><span className={'cosmetic-swatch cs-'+i}>{i===2?<Shield/>:<Shirt/>}</span><span>{c}<small>{i===2?'Identidade da comunidade':'Conceito de capa'}</small></span>{cosmetic===c?<CheckCircle2 size={19}/>:<ChevronRight size={18}/>}</button>)}<div className="info-panel"><Eye size={18}/><p>Cosméticos Vsync precisarão do backend e do módulo no jogo. A visibilidade ficará restrita aos usuários compatíveis do Vsync.</p></div><Button disabled><Lock size={15}/>Disponível em uma próxima etapa</Button></div></div></>;
 const renderDownloads=()=> <><PageHead title="Tudo a caminho." subtitle="Acompanhe cada arquivo até a sua próxima aventura."><Button onClick={()=>void run('diagnostic.export')}><ArrowDownToLine size={16}/>Exportar diagnóstico</Button></PageHead><div className="download-stats"><div><Download size={21}/><span>Na fila<strong>{activeTasks.length}</strong></span></div><div><CheckCircle2 size={21}/><span>Concluídos<strong>{state.tasks.filter(t=>t.status==='completed').length}</strong></span></div><div><Activity size={21}/><span>Velocidade atual<strong>{bytes(state.tasks.find(t=>t.status==='running')?.speed??0)}/s</strong></span></div></div>{state.tasks.length?<div className="download-list">{state.tasks.map(t=><div className="download-item" key={t.id}><div className={'download-status ds-'+t.status}>{t.status==='completed'?<CheckCircle2/>:t.status==='error'?<AlertCircle/>:t.status==='running'?<LoaderCircle className="spin"/>:<Download/>}</div><div className="grow"><div className="download-heading"><h3>{t.name}</h3><Badge tone={t.status==='completed'?'green':t.status==='error'?'yellow':'muted'}>{{running:'Baixando',queued:'Na fila',completed:'Concluído',cancelled:'Cancelado',error:'Falhou'}[t.status]}</Badge></div><p>{t.detail}</p>{t.status==='running'&&<><div className="progress"><span style={{width:t.total?Math.min(100,t.received/t.total*100)+'%':'12%'}}/></div><div className="download-metrics"><span>{bytes(t.received)} / {t.total?bytes(t.total):'Calculando'} • arquivo atual</span><span>{bytes(t.speed)}/s</span></div></>}</div>{['queued','running'].includes(t.status)?<IconButton label="Cancelar download" onClick={()=>void run('download.cancel',{id:t.id})}><X size={18}/></IconButton>:['error','cancelled'].includes(t.status)?<Button onClick={()=>void run('download.retry',{id:t.id})}><RefreshCw size={15}/>Repetir</Button>:null}</div>)}</div>:<Empty icon={<Download size={38}/>} title="O caminho está livre" description="Instalações, modpacks e atualizações aparecem aqui enquanto são baixados."><Button onClick={()=>go('modpacks')}><Compass size={16}/>Explorar modpacks</Button></Empty>}<div className="info-panel"><Info size={18}/><p>Pausa e retomada ainda não são oferecidas neste build. Você pode cancelar e repetir uma tarefa; arquivos completos com hash válido são reaproveitados.</p></div><details className="logs-panel"><summary><Terminal size={16}/>Logs do launcher<span>{state.logs.length} registros</span></summary><pre>{state.logs.join('\n')||'Nenhum registro nesta sessão.'}</pre></details></>;
 const renderSettings=()=>{
  const s=state.settings;
  return <><PageHead title="Do seu jeito, em cada detalhe." subtitle="Ajuste o Vsync para acompanhar o seu ritmo."/><div className="settings-layout"><div className="settings-nav">{settingsTabs.map(([name,Icon])=><button key={name} className={settingsTab===name?'active':''} onClick={()=>setSettingsTab(name)}><Icon size={17}/>{name}</button>)}</div><div className="settings-content"><h2>{settingsTab}</h2>
   {settingsTab==='Geral'&&<><UpdatePanel snapshot={state} run={run}/><Field label="Idioma"><select value="pt-BR" onChange={()=>{}}><option>pt-BR</option></select></Field><Field label="Ao iniciar o Minecraft"><select value={s.behavior} onChange={e=>saveSettings({behavior:e.target.value as SettingsType['behavior']})}><option value="minimize">Minimizar o launcher</option><option value="keep">Manter o launcher aberto</option></select></Field><div className="setting-row"><div><h3>Pasta das instalações</h3><p className="path-text">{s.installRoot}</p></div><Button onClick={()=>void run('settings.root')}><FolderOpen size={15}/>Alterar pasta</Button></div><div className="info-panel"><Shield size={18}/><p>O Vsync mantém os perfis independentes e preserva os mundos ao mover a pasta de instalação.</p></div></>}
   {settingsTab==='Aparência'&&<><Field label="Escala da interface"><div className="range-row"><input type="range" min=".8" max="1.3" step=".05" value={s.scale} onChange={e=>saveSettings({scale:Number(e.target.value)})}/><Badge tone="muted">{Math.round(s.scale*100)}%</Badge></div></Field><Field label="Cor de destaque"><div className="color-options">{['#8B5CF6','#7C3AED','#A78BFA','#6366F1','#C4B5FD'].map(c=><button aria-label={'Usar cor '+c} key={c} className={s.accent===c?'selected':''} style={{background:c}} onClick={()=>saveSettings({accent:c})}>{s.accent===c&&<Check size={16}/>}</button>)}</div></Field><Toggle checked={s.animations} onChange={v=>saveSettings({animations:v})} label="Animações suaves" description="Desative para reduzir os efeitos de movimento."/><Toggle checked={s.reduceInGame} onChange={v=>saveSettings({reduceInGame:v})} label="Economizar durante o jogo" description="Reduz animações enquanto o processo do Minecraft está em execução. O Chromium também limita janelas em segundo plano."/></>}
   {settingsTab==='Minecraft e Java'&&<><div className="system-card"><Monitor size={26}/><div><h3>{(state.system.memory/1024).toFixed(0)} GB de RAM no sistema</h3><p>Reserve memória para o Windows e os aplicativos abertos.</p></div></div><Field label="Memória sugerida para novos perfis" hint="A alocação efetiva é definida individualmente em cada perfil."><div className="range-row"><input type="range" min="2048" max={Math.min(16384,state.system.memory-1024)} step="512" value={s.ram} onChange={e=>saveSettings({ram:Number(e.target.value)})}/><Badge>{(s.ram/1024).toFixed(1)} GB</Badge></div></Field><div className="setting-row"><div><h3>Executável Java</h3><p className="path-text">{s.javaPath||'Automático • Windows x64 usa Temurin verificado'}</p></div><Button onClick={()=>void run('settings.java',undefined,'Java validado e selecionado.')}><FolderOpen size={15}/>Procurar</Button></div><div className="info-panel"><Info size={18}/><p>O perfil inicial 1.21.1 exige Java 21. Outras versões seguem o requisito do manifesto oficial.</p></div><h3 className="settings-subhead">Presets de desempenho</h3>{[['Leve','3 GB sugeridos. Prioriza menos efeitos no launcher.'],['Equilibrado','4 GB sugeridos. Base para jogo e mods moderados.'],['Qualidade','6 GB sugeridos. Base para packs mais exigentes.']].map(([name,text])=><div className="setting-row" key={name}><div><h3>{name}</h3><p>{text} A escolha não instala mods automaticamente.</p></div></div>)}<p className="footnote">Sem promessa de FPS: use o roteiro de benchmark incluído para medir seu computador.</p></>}
   {settingsTab==='Contas'&&<><LaunchModeField mode={s.launchMode} onChange={launchMode=>saveSettings({launchMode})}/>{officialMode?<OfficialConnection state={state} run={run}/>:<><div className="microsoft-card"><div className="microsoft-logo"><i/><i/><i/><i/></div><div><h3>Sua conta. Seu Minecraft.</h3><p>Entre pelo navegador oficial da Microsoft. O Vsync verifica o acesso ao Java Edition.</p></div></div>{state.accounts.map(a=><div className="account-row" key={a.id}><div className="avatar">{a.name[0]}</div><div className="grow"><h3>{a.name}</h3><p>{a.id===state.activeAccountId?'Conta ativa':'Conta salva no cofre do sistema'}</p></div>{a.id!==state.activeAccountId&&<Button onClick={()=>void run('accounts.select',{id:a.id})}>Usar conta</Button>}<IconButton label={'Remover conta '+a.name} onClick={()=>void run('accounts.remove',{id:a.id})}><LogOut size={17}/></IconButton></div>)}<Button variant="primary" disabled={busy>0} onClick={()=>void run('accounts.login',undefined,'Conta conectada com sucesso.')}><LogIn size={17}/>Entrar com Microsoft</Button><AccountValidation key={state.activeAccountId} connected={!!account} run={run}/><div className="divider"/><Field label="Microsoft Client ID do aplicativo" hint="ID público do registro próprio do Vsync, com retorno desktop http://localhost e acesso à API do Minecraft. Nenhum client secret deve ser usado no launcher."><input value={s.clientId} placeholder="00000000-0000-0000-0000-000000000000" onChange={e=>setState({...state,settings:{...s,clientId:e.target.value}})} onBlur={e=>saveSettings({clientId:e.target.value.trim()})}/></Field><Button variant="ghost" onClick={()=>void run('external',{url:'https://learn.microsoft.com/en-us/entra/identity-platform/quickstart-register-app'})}><ExternalLink size={14}/>Como registrar o aplicativo</Button><div className="info-panel"><Lock size={18}/><p>Sessões são criptografadas pelo armazenamento seguro do sistema. A entrada é bloqueada quando esse cofre não está disponível.</p></div></>}</>}
   {settingsTab==='Downloads'&&<><Field label="Downloads paralelos de arquivos do jogo"><select value={s.downloadConcurrency} onChange={e=>saveSettings({downloadConcurrency:Number(e.target.value)})}>{[1,2,4,6,8].map(n=><option key={n} value={n}>{n} arquivos</option>)}</select></Field><div className="setting-row"><div><h3>Integridade dos arquivos</h3><p>Arquivos oficiais e componentes são comparados com os hashes informados por suas fontes.</p></div><Badge tone="green"><Check size={12}/>Ativa</Badge></div><Button onClick={()=>go('downloads')}><Download size={16}/>Abrir central de downloads</Button></>}
   {settingsTab==='Privacidade'&&<><Toggle checked={s.hidePresence} onChange={v=>saveSettings({hidePresence:v})} label="Ocultar minha presença" description="Controla a presença do Vsync no Discord."/><Toggle checked={s.hideServer} onChange={v=>saveSettings({hideServer:v})} label="Ocultar servidor atual" description="O Discord não recebe o endereço do servidor nesta versão."/><div className="setting-row"><div><h3>Telemetria</h3><p>Este build não envia telemetria do Vsync. Os provedores de autenticação e downloads recebem as requisições necessárias.</p></div><Badge tone="muted">Sem coleta Vsync</Badge></div></>}
   {settingsTab==='Integrações'&&<><DiscordIntegration snapshot={state} save={saveSettings} open={()=>void run('external',{url:'https://discord.com/developers/applications'})}/><div className="setting-row"><div><h3>Modrinth</h3><p>Catálogo público oficial de mods, modpacks, texturas e shaders.</p></div><Badge tone="green">Implementado</Badge></div><div className="setting-row"><div><h3>CurseForge</h3><p>Organização inspirada no CurseForge. Integração com sua API e chave ainda não implementada.</p></div><Badge tone="yellow">Planejado</Badge></div><div className="setting-row"><div><h3>Amigos e cosméticos Vsync</h3><p>Backend e integração de presença ainda não conectados.</p></div><Badge tone="yellow">Planejado</Badge></div></>}
   {settingsTab==='Avançado'&&<><ProfileValidation profileId={profile?.id} run={run}/><div className="setting-row"><div><h3>Diagnóstico com dados reduzidos</h3><p>Exporta versões, componentes e logs com remoção de tokens, e-mails, IPs e caminhos de usuário reconhecidos.</p></div><Button onClick={()=>void run('diagnostic.export')}><ArrowDownToLine size={15}/>Exportar</Button></div><div className="module-card"><div className="module-card-title"><Keyboard size={23}/><div><h3>Vsync HUD</h3><p>Módulo Fabric separado • Minecraft 1.21.1</p></div></div><p>FPS, CPS, keystrokes, coordenadas, armadura, poções, sprint, zoom e editor de HUD. Requer Fabric API e o JAR compilado do módulo.</p><Button onClick={()=>profile&&void run('profile.module',{id:profile.id},'Módulo instalado no perfil selecionado.')} disabled={!profile||!state.system.moduleAvailable}><Download size={15}/>{state.system.moduleAvailable?'Instalar no perfil selecionado':'Compile o módulo para instalar'}</Button></div><p className="footnote">Vsync Client {state.system.appVersion} • {state.system.platform} • Projeto independente, sem vínculo com Mojang, Microsoft, Lunar Client ou CurseForge.</p></>}
  </div></div></>;
 };
 return <div className={'app '+(!friendsOpen?'rail-closed':'')} style={{fontSize:14*state.settings.scale}}>
  <header className="titlebar"><button className="title-brand" onClick={()=>go('home')}><img src="./assets/icon.svg" alt=""/><span>Vsync <b>Client</b></span><span className="alpha-label">ALPHA</span></button><div className="titlebar-drag"/>{!state.system.native&&<span className="preview-tag">Prévia da interface</span>}{busy>0&&<LoaderCircle size={15} className="spin busy-indicator"/>}<div className="top-actions"><IconButton label="Atualizações do Vsync" className={state.updates.state==='available'||state.updates.state==='ready'?'update-available':''} onClick={()=>settings('Geral')}><RefreshCw size={17}/>{['available','ready'].includes(state.updates.state)&&<span className="notification-dot"/>}</IconButton><div className="notification-wrap"><IconButton label="Notificações" onClick={()=>setNotifications(!notifications)}><Bell size={17}/><span className="notification-dot"/></IconButton>{notifications&&<div className="notification-pop"><h3>Novidades do Vsync</h3>{news.map((n,i)=><button key={n.title} onClick={()=>{setModal({type:'news',index:i});setNotifications(false);}}><span className="notification-bullet"/><div><strong>{n.title}</strong><small>{n.date}</small></div><ChevronRight size={14}/></button>)}</div>}</div><button className="top-account" onClick={()=>settings('Contas')}><div className="avatar tiny">{account?.name[0]??<img src="./assets/panda.png" alt=""/>}</div><span>{officialMode?'Minecraft Launcher':account?.name??'Conectar conta'}</span><ChevronDown size={13}/></button><span className="title-separator"/><div className="window-controls"><IconButton label="Minimizar" onClick={()=>void run('window.minimize')}><Minus size={15}/></IconButton><IconButton label="Maximizar ou restaurar" onClick={()=>void run('window.maximize')}><Square size={12}/></IconButton><IconButton label="Fechar janela" className="close-window" onClick={()=>void run('window.close')}><X size={16}/></IconButton></div></div></header>
  <aside className="sidebar"><Brand/><nav aria-label="Navegação principal">{nav.map(item=><div key={item.id}>{item.group&&<div className="nav-group">{item.group}</div>}<button className={'nav-item '+(page===item.id?'active':'')} onClick={()=>go(item.id)}><item.icon size={18}/><span>{item.name}</span>{item.id==='downloads'&&activeTasks.length>0&&<b>{activeTasks.length}</b>}{item.id==='cosmetics'&&<span className="nav-new"/>}</button></div>)}</nav><button className="sidebar-community" onClick={()=>go('friends')}><div className="community-icon"><Users size={19}/></div><span>Jogue do seu jeito<small>O Vsync está só começando.</small></span><ArrowUpRight size={15}/></button><div className="sidebar-footer"><span className="tiny-dot"/>Vsync Client <span>{state.system.appVersion}</span></div></aside>
  <main className="main" id="main-content"><div className="content">{page==='home'?renderHome():page==='profiles'?renderProfiles():page==='fps'?<PerformancePage key={profile?.id} state={state} profile={profile} bridge={bridge} run={run} busy={busy>0} onProfiles={()=>go('profiles')}/>:['mods','modpacks','textures'].includes(page)?renderCatalog():page==='servers'?renderServers():page==='friends'?renderFriends():page==='cosmetics'?renderCosmetics():page==='downloads'?renderDownloads():renderSettings()}</div></main>
  <aside className={'friends-rail '+(!friendsOpen?'collapsed':'')}><div className="rail-title">{friendsOpen&&<><Users size={17}/><h2>Amigos</h2><span>0</span></>}<IconButton label={friendsOpen?'Recolher amigos':'Mostrar amigos'} onClick={()=>setFriendsOpen(!friendsOpen)}>{friendsOpen?<ChevronRight size={16}/>:<ChevronLeft size={16}/>}</IconButton></div>{friendsOpen&&<><div className="friends-search" onClick={()=>go('friends')}><Search size={15}/><span>Encontre seu grupo</span></div><div className="friends-empty"><div className="friends-empty-illustration"><Users size={33}/><span>+</span></div><h3>Melhor em boa companhia.</h3><p>Seu próximo duo pode<br/>começar por aqui.</p><Button onClick={()=>go('friends')}><Plus size={15}/>Conhecer o social</Button><span className="social-status">Em desenvolvimento</span></div><div className="rail-bottom"><div className="rail-tip"><span className="tip-icon"><Keyboard size={17}/></span><div><small>DICA VSYNC</small><h3>Uma tecla. Seu HUD.</h3><p>O módulo Vsync abre com <kbd>Right Shift</kbd>.</p><button onClick={()=>settings('Avançado')}>Conhecer o módulo<ArrowUpRight size={13}/></button></div></div><button className="rail-user" onClick={()=>settings('Contas')}><div className="avatar"><img src="./assets/panda.png" alt=""/></div><div><strong>{officialMode?'Minecraft Launcher':account?.name??'Sua próxima aventura'}</strong><small>{officialMode?'Login no aplicativo oficial':account?'Conta Microsoft conectada':'Entre com Microsoft'}</small></div><Settings size={15}/></button></div></>}</aside>
  <footer className="launchbar"><div className="launch-profile">{profile?<><ProfileArt preset={profile.preset} image={profile.image}/><button onClick={()=>go('profiles')}><small>PERFIL SELECIONADO</small><strong>{profile.name}<ChevronDown size={14}/></strong><span>{profile.gameVersion}<i/> <span className="capitalize">{profile.loader}</span></span></button><IconButton label="Ajustar perfil" onClick={()=>setModal({type:'profile',profile})}><SlidersHorizontal size={18}/></IconButton></>:<Button onClick={()=>setModal({type:'profile'})}><Plus size={17}/>Criar perfil</Button>}</div><div className="launch-status">{state.game.state==='error'?<><AlertCircle size={16}/><span>{state.game.message}</span></>:activeTasks.length?<><LoaderCircle className="spin" size={16}/><span>{activeTasks.length} tarefa(s) na fila<button onClick={()=>go('downloads')}>Acompanhar downloads<ArrowRight size={12}/></button></span></>:officialMode?<><Gamepad2 size={18}/><span>{state.official.status==='handoff'?'Continue no Minecraft Launcher':'Login e jogo pelo launcher oficial'}<small>{state.official.status==='handoff'?'Selecione Vsync • '+(profile?.name??'seu perfil'):'Mundos e mods continuam na pasta do seu perfil Vsync'}</small></span></>:<><Shield size={18}/><span>{profile?.installed?'Pronto para a próxima aventura':'Instalação verificada e independente'}<small>{profile?.installed?'Mundos e mods organizados no seu perfil':'Os arquivos serão baixados das fontes originais'}</small></span></>}</div><div className="launch-primary"><Button variant="primary" onClick={launch} disabled={activeTasks.length>0||['running','preparing'].includes(state.game.state)}>{['running','preparing'].includes(state.game.state)||activeTasks.length?<LoaderCircle size={20} className={state.game.state==='running'?'':'spin'}/>:<Play size={19} fill="currentColor"/>}{launchLabel}</Button><small>{officialMode?'Minecraft Launcher oficial':profile?.installed?'Minecraft Java Edition':'Minecraft '+(profile?.gameVersion??'Java Edition')}</small></div></footer>
  {toast&&<div className={'toast '+(toast.error?'error':'')} role={toast.error?'alert':'status'}>{toast.error?<AlertCircle size={19}/>:<CheckCircle2 size={19}/>}<p>{toast.message}</p><IconButton label="Fechar aviso" onClick={()=>setToast(null)}><X size={15}/></IconButton></div>}
  {modal?.type==='profile'&&<ProfileEditor state={state} profile={modal.profile} preset={modal.preset} close={modalClose} run={run} onExport={p=>setModal({type:'export',profile:p})}/>}
  {modal?.type==='project'&&<ProjectModal project={modal.project} profile={profile} close={modalClose} install={id=>installProject(modal.project,id)} run={run}/>}
  {modal?.type==='server'&&<ServerEditor profiles={state.profiles} selectedId={state.selectedProfileId} close={modalClose} run={run}/>}
  {modal?.type==='export'&&<ExportDialog profile={modal.profile} close={modalClose} run={run}/>}
  {modal?.type==='news'&&<Modal title={news[modal.index].title} subtitle={news[modal.index].tag+' • '+news[modal.index].date} onClose={modalClose}><div className="modal-body"><p className="long-copy">{news[modal.index].body}</p><div className="modal-footer"><Button variant="primary" onClick={modalClose}>Entendi<Check size={16}/></Button></div></div></Modal>}
  {modal?.type==='info'&&<Modal title={modal.title} onClose={modalClose}><div className="modal-body"><p className="long-copy">{modal.text}</p><Button onClick={modalClose}>Entendi</Button></div></Modal>}
 </div>;
}
type Run=<T=unknown>(method:string,args?:unknown,success?:string)=>Promise<T|undefined>;
function ProfileEditor({state,profile,preset,close,run,onExport}:{state:Snapshot;profile?:Profile;preset?:number;close:()=>void;run:Run;onExport:(p:Profile)=>void}){
 const base=preset!==undefined?PRESETS[preset]:undefined;
 const [form,setForm]=useState({name:profile?.name??base?.name??'Novo perfil',image:profile?.image??'',description:profile?.description??base?.description??'Seu mundo, do seu jeito.',gameVersion:profile?.gameVersion??'1.21.1',loader:profile?.loader??'fabric',loaderVersion:profile?.loaderVersion??'',ram:profile?.ram??base?.ram??state.settings.ram,width:profile?.width??1280,height:profile?.height??720,javaPath:profile?.javaPath??state.settings.javaPath,jvmArgs:profile?.jvmArgs.join('\n')??'',preset:profile?.preset??base?.preset??'Equilibrado',accent:profile?.accent??'#8B5CF6'});
 const [tab,setTab]=useState('Geral'),[versions,setVersions]=useState(['1.21.1']),[loaders,setLoaders]=useState<Record<string,string[]>>({vanilla:[],fabric:[],quilt:[],forge:[],neoforge:[]}),[loading,setLoading]=useState(false),[error,setError]=useState(''),[saving,setSaving]=useState(false);
 const patch=(x:Partial<typeof form>)=>setForm(f=>({...f,...x}));
 useEffect(()=>{let live=true;bridge.call<string[]>('versions').then(v=>{if(live)setVersions(v);}).catch(()=>{if(live)setError('Sem acesso à lista oficial. A versão inicial permanece disponível.');});return()=>{live=false;};},[]);
 useEffect(()=>{let live=true;setLoading(true);bridge.call<any>('loaders',{version:form.gameVersion}).then(v=>{if(live){setLoaders(v);setError('');}}).catch(e=>{if(live)setError(e.message);}).finally(()=>{if(live)setLoading(false);});return()=>{live=false;};},[form.gameVersion]);
 const submit=async()=>{setSaving(true);const result=await run(profile?'profile.update':'profile.create',{...form,jvmArgs:form.jvmArgs.split('\n').map(s=>s.trim()).filter(Boolean),...(profile?{id:profile.id}:{})},profile?'Perfil atualizado.':'Perfil criado.');setSaving(false);if(result)close();};
 return <Modal title={profile?'Seu perfil, seus detalhes.':'O começo de uma nova aventura.'} subtitle={profile?profile.name:'Crie uma instalação independente do Minecraft.'} onClose={close} wide><div className="profile-modal-layout"><div className="profile-editor-preview"><ProfileArt preset={form.preset} image={form.image}/><img src="./assets/panda.png" alt="Mascote Vsync"/><h3>{form.name}</h3><Badge>{form.gameVersion}</Badge>{profile&&<Button onClick={()=>void run<string>('profile.image',{id:profile.id}).then(image=>image&&patch({image}))}><ImageIcon size={14}/>Alterar imagem</Button>}<p>{base?.components??'Mods, mundos e configurações ficam separados neste perfil.'}</p></div><div className="profile-editor-form"><div className="tabs">{['Geral','Desempenho','Avançado'].map(t=><button key={t} className={tab===t?'active':''} onClick={()=>setTab(t)}>{t}</button>)}</div><div className="editor-fields">
 {tab==='Geral'&&<><Field label="Nome do perfil"><input autoFocus maxLength={60} value={form.name} onChange={e=>patch({name:e.target.value})}/></Field><Field label="Descrição"><textarea rows={2} maxLength={500} value={form.description} onChange={e=>patch({description:e.target.value})}/></Field><div className="field-grid"><Field label="Versão do Minecraft"><select value={form.gameVersion} onChange={e=>patch({gameVersion:e.target.value,loaderVersion:''})}>{[...new Set([form.gameVersion,...versions])].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Loader"><select value={form.loader} onChange={e=>patch({loader:e.target.value as Profile['loader'],loaderVersion:''})}><option value="vanilla">Vanilla</option><option value="fabric" disabled={loading||!loaders.fabric?.length}>Fabric {loading?'• consultando…':!loaders.fabric?.length?'• indisponível':''}</option><option value="quilt" disabled={loading||!loaders.quilt?.length}>Quilt {!loaders.quilt?.length?'• indisponível':''}</option><option value="forge" disabled>Forge • planejado</option><option value="neoforge" disabled>NeoForge • planejado</option></select></Field></div>{form.loader!=='vanilla'&&<Field label="Versão do loader"><select value={form.loaderVersion} onChange={e=>patch({loaderVersion:e.target.value})}><option value="">Última estável compatível</option>{loaders[form.loader]?.map(v=><option key={v}>{v}</option>)}</select></Field>}{error&&<div className="form-error"><AlertCircle size={16}/>{error}</div>}</>}
 {tab==='Desempenho'&&<><Field label="Preset de desempenho"><select value={form.preset} onChange={e=>{const v=e.target.value as Profile['preset'];patch({preset:v,ram:v==='Leve'?3072:v==='Qualidade'?6144:4096});}}><option>Leve</option><option>Equilibrado</option><option>Qualidade</option></select></Field><Field label="Memória RAM" hint="Não instala mods automaticamente. Ajuste de acordo com o pack e deixe memória livre para o sistema."><div className="range-row"><input type="range" min={1024} max={Math.min(16384,state.system.memory-1024)} step={512} value={form.ram} onChange={e=>patch({ram:Number(e.target.value)})}/><Badge>{(form.ram/1024).toFixed(1)} GB</Badge></div></Field><div className="field-grid"><Field label="Largura"><input type="number" min={640} value={form.width} onChange={e=>patch({width:Number(e.target.value)})}/></Field><Field label="Altura"><input type="number" min={360} value={form.height} onChange={e=>patch({height:Number(e.target.value)})}/></Field></div><div className="info-panel"><Info size={17}/><p>As recomendações são pontos de partida. Não há resultados de FPS medidos neste ambiente.</p></div></>}
 {tab==='Avançado'&&<><Field label="Java do perfil" hint="Selecione um novo executável nas configurações globais de Minecraft e Java."><input value={form.javaPath||'Automático • conforme o manifesto do Minecraft'} readOnly/></Field><Field label="Argumentos JVM" hint="Um argumento por linha. Apenas ajuste se souber o efeito de cada opção."><textarea rows={4} placeholder="-XX:+UseG1GC" value={form.jvmArgs} onChange={e=>patch({jvmArgs:e.target.value})}/></Field>{profile&&<div className="profile-operations"><Button onClick={()=>void run('profile.duplicate',{id:profile.id},'Perfil duplicado sem copiar mundos.').then(r=>r&&close())}><Copy size={15}/>Duplicar</Button><Button onClick={()=>onExport(profile)}><Upload size={15}/>Exportar</Button><Button onClick={()=>void run('profile.repair',{id:profile.id},'Reparação adicionada à fila.')}><RefreshCw size={15}/>Reparar</Button><Button onClick={()=>void run('profile.folder',{id:profile.id})}><FolderOpen size={15}/>Abrir pasta</Button><Button variant="danger" onClick={()=>void run('profile.delete',{id:profile.id}).then(r=>r&&close())}><Trash2 size={15}/>Excluir perfil</Button></div>}</>}
 </div><div className="modal-footer"><Button onClick={close}>Cancelar</Button><Button variant="primary" disabled={!form.name.trim()||saving||loading} onClick={()=>void submit()}>{saving?<LoaderCircle className="spin" size={16}/>:<Check size={16}/>} {profile?'Salvar alterações':'Criar perfil'}</Button></div></div></div></Modal>;
}
function ProjectModal({project,profile,close,install,run}:{project:Project;profile?:Profile;close:()=>void;install:(version?:string)=>void;run:Run}){
 const [data,setData]=useState<ProjectDetail|null>(null),[error,setError]=useState(''),[tab,setTab]=useState('Visão geral'),[version,setVersion]=useState('');
 useEffect(()=>{if(!profile)return;let live=true;bridge.call<ProjectDetail>('catalog.detail',{project:project.id,profileId:profile.id}).then(d=>{if(live){setData(d);setVersion(d.versions.find(v=>project.project_type!=='mod'||v.loaders.includes(profile.loader))?.id??'');}}).catch(e=>{if(live)setError(e.message);});return()=>{live=false;};},[project.id,profile?.id]);
 const versions=data?.versions.filter(v=>project.project_type!=='mod'||v.loaders.includes(profile?.loader??''))??[];const selected=versions.find(v=>v.id===version);
 return <Modal title={project.title} subtitle={'Por '+project.author+' • Modrinth'} onClose={close} wide><div className="project-modal-banner"><ProjectArt project={project}/><div><Badge>Projeto da comunidade</Badge><h2>{project.title}</h2><p>{project.description}</p></div></div><div className="modal-body"><div className="tabs">{['Visão geral','Versões','Dependências','Changelog'].map(t=><button key={t} className={tab===t?'active':''} onClick={()=>setTab(t)}>{t}</button>)}</div>{error?<div className="form-error"><AlertCircle size={18}/>{error}</div>:!data?<Loading label="Consultando arquivos compatíveis…"/>:<div className="project-detail-content">{tab==='Visão geral'&&<><p>{project.description}</p><div className="detail-specs"><div><small>Origem</small><strong>Modrinth</strong></div><div><small>Perfil de destino</small><strong>{profile?.name}</strong></div><div><small>Versão</small><strong>{profile?.gameVersion} • {profile?.loader}</strong></div><div><small>Licença</small><strong>{data.project.license?.id??'Consulte o projeto'}</strong></div></div><p className="footnote">A página original contém a documentação completa, imagens, autoria e termos do projeto.</p></>}{tab==='Versões'&&<>{versions.length?versions.slice(0,20).map(v=><button key={v.id} className={'version-row '+(version===v.id?'active':'')} onClick={()=>setVersion(v.id)}><span><strong>{v.name}</strong><small>{v.game_versions.join(', ')} • {v.loaders.join(', ')}</small></span>{v.id===version?<CheckCircle2 size={18}/>:<ChevronRight size={16}/>}</button>):<p>Não há versões compatíveis para o perfil selecionado.</p>}</>}{tab==='Dependências'&&<>{selected?.dependencies.length?selected.dependencies.map((d,i)=><div key={i} className="dependency-row"><Package size={17}/><span>{d.project_id??d.version_id??'Arquivo externo'}</span><Badge tone={d.dependency_type==='incompatible'?'yellow':'muted'}>{d.dependency_type==='required'?'Obrigatória':d.dependency_type==='incompatible'?'Incompatível':'Opcional'}</Badge></div>):<p>Nenhuma dependência declarada para esta versão.</p>}<p className="footnote">IDs são os identificadores originais do catálogo. Dependências obrigatórias são resolvidas na instalação. Isso não garante ausência de conflitos não declarados.</p></>}{tab==='Changelog'&&<pre className="changelog">{selected?.changelog||'O autor não forneceu notas para esta versão.'}</pre>}</div>}<div className="project-install-bar"><Button onClick={()=>void run('external',{url:'https://modrinth.com/'+project.project_type+'/'+project.slug})}><ExternalLink size={15}/>Página original / download manual</Button><div className="grow"/>{versions.length>0&&<select aria-label="Versão do componente" value={version} onChange={e=>setVersion(e.target.value)}>{versions.map(v=><option key={v.id} value={v.id}>{v.version_number}</option>)}</select>}<Button variant="primary" disabled={!selected||!profile} onClick={()=>install(version)}><Download size={16}/>Instalar{project.project_type==='modpack'?' como novo perfil':''}</Button></div>{!selected&&data&&<p className="footnote">Nenhum arquivo compatível disponível. Consulte a página original ou selecione outro perfil.</p>}</div></Modal>;
}
function ServerEditor({profiles,selectedId,close,run}:{profiles:Profile[];selectedId:string;close:()=>void;run:Run}){
 const [name,setName]=useState(''),[address,setAddress]=useState(''),[profileId,setProfileId]=useState(selectedId),[favorite,setFavorite]=useState(true);
 return <Modal title="Um novo lugar para jogar." subtitle="Associe o servidor a um dos seus perfis." onClose={close}><form className="modal-body" onSubmit={e=>{e.preventDefault();void run('server.save',{name,address,profileId,favorite},'Servidor adicionado.').then(result=>{if(result)close();});}}><Field label="Nome do servidor"><input required value={name} onChange={e=>setName(e.target.value)} placeholder="Meu servidor"/></Field><Field label="Endereço" hint="Use o domínio ou domínio:porta."><input required value={address} onChange={e=>setAddress(e.target.value)} placeholder="jogar.exemplo.com.br"/></Field><Field label="Perfil para conectar"><select required value={profileId} onChange={e=>setProfileId(e.target.value)}>{profiles.map(p=><option key={p.id} value={p.id}>{p.name} • {p.gameVersion}</option>)}</select></Field><Toggle checked={favorite} onChange={setFavorite} label="Adicionar aos favoritos"/><div className="modal-footer"><Button onClick={close}>Cancelar</Button><Button type="submit" variant="primary" disabled={!name||!address||!profileId}><Plus size={16}/>Adicionar servidor</Button></div></form></Modal>;
}
function ExportDialog({profile,close,run}:{profile:Profile;close:()=>void;run:Run}){const [worlds,setWorlds]=useState(false);return <Modal title="Leve seu perfil com você." subtitle={profile.name} onClose={close}><div className="modal-body"><p className="long-copy">O arquivo .vsync.zip inclui mods e configurações do perfil. Credenciais e cache do Minecraft ficam fora da exportação.</p><Toggle checked={worlds} onChange={setWorlds} label="Incluir mundos salvos" description="Aumenta o arquivo e inclui os mundos da pasta saves."/><div className="modal-footer"><Button onClick={close}>Cancelar</Button><Button variant="primary" onClick={()=>void run('profile.export',{id:profile.id,worlds},'Perfil exportado.').then(r=>r&&close())}><Upload size={16}/>Exportar perfil</Button></div></div></Modal>;}
